// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address caller, address adr, bytes memory data) public {
        vm.assume(caller != address(0) && caller != address(c) && caller != address(this));
        vm.assume(adr != address(0) && adr != address(c) && adr != address(this));
        vm.deal(caller, 0);
        vm.prank(caller);
        bool ok;
        try c.Command(adr, data) { ok = true; } catch { ok = false; }
        bool isOwner = (caller == c.Owner());
        assertTrue(ok == isOwner);
    }
}
